(() => {
  const G = window.__game, c = document.getElementById('newCard'), b = document.getElementById('newName');
  const langs = ['en','es','pt','fr','de','tr','ru','ja','ko','id','zh-Hant','zh-Hans'];
  const cjk = (l) => /^(ja|ko|zh)/.test(l);
  const ids = ['mush','swarm','ring','move','spikeLow','mushChain','ringArc','fan','saw','spikeHigh','tunnel','pad','boost'];
  const bad = [], all = [];
  c.style.animation = 'none';
  for (const l of langs) {
    G.i18n.setLang(l);
    for (const id of ids) {
      const name = G.i18n.t('new.' + id);
      G.ui.newCard(name); c.style.animation = 'none'; c.style.opacity = 1; c.style.transform = 'translateX(-50%)';
      const fs = parseFloat(getComputedStyle(b).fontSize);
      let issue = '';
      if (b.scrollWidth > b.clientWidth + 0.5) issue += 'overflow ';
      if (fs < 24) issue += 'small ';
      if (!cjk(l)) {
        const tn = b.firstChild; const re = /\S+/g; let m;
        while ((m = re.exec(tn.data))) {
          const r = document.createRange(); r.setStart(tn, m.index); r.setEnd(tn, m.index + m[0].length);
          const tops = new Set([...r.getClientRects()].map((q) => Math.round(q.top / 4)));
          if (tops.size > 1) { issue += 'split:' + m[0] + ' '; break; }
        }
      }
      all.push({ l, id, name, fs, w: Math.round(b.scrollWidth), cw: Math.round(b.clientWidth), issue });
      if (issue) bad.push({ l, name, fs, issue });
    }
  }
  G.ui.newCard(null); G.i18n.setLang('en');
  window.__ncBad = bad.length;
  const worst = all.slice().sort((a, z) => (a.fs - z.fs) || (z.w / z.cw - a.w / a.cw)).slice(0, 5).map((o) => `${o.l}|${o.name}|${o.fs}px`);
  return JSON.stringify({ combos: all.length, bad: bad.length, badList: bad.slice(0, 8), worst5: worst });
})()
